package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	// Read n (discarded)
	scanner.Scan()

	// Read m
	scanner.Scan()
	m, _ := strconv.Atoi(scanner.Text())

	// Read remaining integers into gs
	var gs []int
	for scanner.Scan() {
		val, _ := strconv.Atoi(scanner.Text())
		gs = append(gs, val)
	}

	b := 0
	res := 0

	for _, v := range gs {
		if b+v > m {
			res++
			b = v
		} else {
			b += v
		}
	}

	if b > 0 {
		res++
	}

	fmt.Println(res)
}

